compile.workshop:
variables {
    global:
        0: state
}

rule ("conditional goto") {
    event {
        Ongoing - Global;
    }
    actions {
        Skip If(Compare(Global.state, ==, 1), 1);
        Set Global Variable(state, 2);
        //done:
        Set Global Variable(state, 3);
    }
}

rule ("nested conditional goto") {
    event {
        Ongoing - Global;
    }
    actions {
        If(Compare(Global.state, ==, 1));
            Skip If(Compare(Global.state, ==, 2), 2);
        End;
        Set Global Variable(state, 4);
        //nested_done:
        Set Global Variable(state, 5);
    }
}

rule ("conditional goto with else") {
    event {
        Ongoing - Global;
    }
    actions {
        If(Compare(Global.state, ==, 1));
            Skip(4);
        Else;
            Set Global Variable(state, 6);
        End;
        Set Global Variable(state, 7);
        //else_done:
        Set Global Variable(state, 8);
    }
}

rule ("conditional goto after mutation") {
    event {
        Ongoing - Global;
    }
    actions {
        If(Compare(Global.state, ==, 1));
            Set Global Variable(state, 2);
            Skip(2);
        End;
        Set Global Variable(state, 3);
        //mutated_done:
        Set Global Variable(state, 4);
    }
}

rule ("leading goto with tail") {
    event {
        Ongoing - Global;
    }
    actions {
        If(Compare(Global.state, ==, 1));
            Skip(2);
            Set Global Variable(state, 9);
        End;
        //leading_done:
        Set Global Variable(state, 10);
    }
}

